#!/system/bin/sh
# Root My Pixel — KernelSU Complete Setup
# Self-contained with embedded payloads — works without network, APK, or external files

set -e

# Configuration
TEMP_DIR="/data/local/tmp"
WORK_DIR="$TEMP_DIR/rmp-setup"
HELPER_FILE="$TEMP_DIR/helper.so"
EXPLOIT_FILE="$TEMP_DIR/exploit.so"
KSUD_FILE="$TEMP_DIR/ksud"
EXPLOIT_LOG="$TEMP_DIR/exploit.log"

# Logging
log() {
    local level="$1"; shift
    local ts=$(date '+%H:%M:%S')
    echo "[$ts] [$level] $*"
}

info() { log "INFO" "$@"; }
warn() { log "WARN" "$@"; }
fatal() { log "FATAL" "$@"; exit 1; }

# Device detection
detect_device() {
    info "=== DEVICE DETECTION ==="
    DEVICE=$(getprop ro.product.device 2>/dev/null || echo "")
    BUILD=$(getprop ro.build.display.id 2>/dev/null || echo "")
    MODEL=$(getprop ro.product.model 2>/dev/null || echo "")
    KERNEL=$(cat /proc/version 2>/dev/null | grep -o '[0-9]\+\.[0-9]\+\.[0-9]\+' | head -1)
    
    [ -z "$DEVICE" ] && fatal "Cannot detect device"
    [ -z "$BUILD" ] && fatal "Cannot detect build"
    [ -z "$KERNEL" ] && fatal "Cannot detect kernel"
    
    info "Device: $DEVICE ($MODEL)"
    info "Build: $BUILD"
    info "Kernel: $KERNEL"
}

# Profile matching (hardcoded for supported devices)
get_profile() {
    case "$DEVICE:$KERNEL:$BUILD" in
        tegu:6.1.157:CP2A.260705.006)
            echo "android14-6.1"
            return 0
            ;;
        tegu:6.1.157:CP2A.260805.005)
            echo "android14-6.1"
            return 0
            ;;
        panther:6.1.157:CP2A.260705.006)
            echo "android14-6.1"
            return 0
            ;;
        panther:6.1.124:BP2A.250705.008)
            echo "android14-6.1"
            return 0
            ;;
        lynx:6.1.157:CP2A.260705.006)
            echo "android14-6.1"
            return 0
            ;;
        mustang:6.6.118:CP2A.260705.006)
            echo "android15-6.6"
            return 0
            ;;
    esac
    
    warn "Device not in hardcoded profiles"
    return 1
}

# Extract embedded payloads (base64 → binary)
extract_payloads() {
    info ""
    info "=== EXTRACTING PAYLOADS ==="
    mkdir -p "$TEMP_DIR" 2>/dev/null || true
    
    # Create work directory
    mkdir -p "$WORK_DIR" 2>/dev/null || true
    
    # Helper binary (libcve43499root.so)
    info "Extracting helper..."
    echo "$HELPER_B64" | base64 -d > "$HELPER_FILE" || fatal "Helper extraction failed"
    chmod 755 "$HELPER_FILE"
    [ -s "$HELPER_FILE" ] || { fatal "Helper file is empty or extraction failed"; }
    info "✓ Helper extracted"
    
    # Exploit binary
    info "Extracting exploit..."
    echo "$EXPLOIT_B64" | base64 -d > "$EXPLOIT_FILE" || fatal "Exploit extraction failed"
    chmod 755 "$EXPLOIT_FILE"
    [ -s "$EXPLOIT_FILE" ] || { fatal "Exploit file is empty or extraction failed"; }
    info "✓ Exploit extracted"
    
    # ksud binary
    info "Extracting ksud..."
    echo "$KSUD_B64" | base64 -d > "$KSUD_FILE" || fatal "ksud extraction failed"
    chmod 755 "$KSUD_FILE"
    [ -s "$KSUD_FILE" ] || { fatal "ksud file is empty or extraction failed"; }
    info "✓ ksud extracted"
}

# Execute exploit
execute_exploit() {
    info ""
    info "=== RUNNING EXPLOIT ==="
    info "Helper: $HELPER_FILE"
    info "Exploit: $EXPLOIT_FILE"
    
    echo ">>> Ready to execute exploit? [y/n]: "; read ans
    case "$ans" in
        y|yes) ;;
        *) fatal "Exploit cancelled" ;;
    esac
    
    # Run exploit with timeout (no timeout command on Android, use background + manual check)
    local start=$(date +%s)
    "$HELPER_FILE" --run-payload "$EXPLOIT_FILE" "$HELPER_FILE" "$EXPLOIT_LOG" 2>&1 &
    local pid=$!
    
    # Monitor progress
    while true; do
        if ! kill -0 $pid 2>/dev/null; then
            break
        fi
        sleep 2
        if [ -f "$EXPLOIT_LOG" ]; then
            tail -1 "$EXPLOIT_LOG"
        fi
        
        local elapsed=$(($(date +%s) - start))
        if [ $elapsed -gt 1800 ]; then
            kill $pid 2>/dev/null || true
            fatal "Exploit timeout"
        fi
    done
    
    wait $pid || fatal "Exploit failed (exit code $?)"
    
    # Verify success
    if grep -q "done=1" "$EXPLOIT_LOG" 2>/dev/null && grep -q "root=1" "$EXPLOIT_LOG" 2>/dev/null; then
        info "✓ Exploit successful"
        return 0
    fi
    
    fatal "Exploit did not complete successfully"
}

# Install KernelSU
install_kernelsu() {
    local kmi="$1"
    
    info ""
    info "=== SETTING UP KERNELSU ==="
    info "KMI: $kmi"
    
    # Create directories
    "$HELPER_FILE" -c "mkdir -p /data/adb && chmod 700 /data/adb" 2>/dev/null || true
    
    # Set SELinux permissive
    "$HELPER_FILE" -c "setenforce 0" 2>/dev/null || true
    
    # Stage and run ksud
    "$HELPER_FILE" -c "chmod 755 $KSUD_FILE" 2>/dev/null || true
    info "Running ksud late-load (KMI=$kmi)..."
    "$HELPER_FILE" -c "$KSUD_FILE late-load --kmi $kmi" 2>/dev/null || true
    
    # Wait for module to load
    sleep 2
    if "$HELPER_FILE" -c "test -e /dev/kernelsu" 2>/dev/null; then
        info "✓ KernelSU verified (/dev/kernelsu exists)"
        return 0
    fi
    
    warn "KernelSU verification inconclusive (module may still be loading)"
    return 0
}

# Main execution
main() {
    info "╔════════════════════════════════════════════╗"
    info "║  Root My Pixel — KernelSU Setup            ║"
    info "║  Direct Execution (No Detection)           ║"
    info "╚════════════════════════════════════════════╝"
    
    # Hardcoded for tegu/6.1.157/CP2A.260805.005
    DEVICE="tegu"
    KERNEL="6.1.157"
    BUILD="CP2A.260805.005"
    MODEL="Pixel 9a"
    
    info "Device: $DEVICE ($MODEL)"
    info "Build: $BUILD"
    info "Kernel: $KERNEL"
    
    # Get KMI (hardcoded for this kernel version)
    local kmi="android14-6.1"
    
    info "Profile: KMI=$kmi"
    
    echo ">>> Continue? [y/n]: "; read ans
    case "$ans" in
        y|yes) ;;
        *) info "Cancelled"; exit 0 ;;
    esac
    
    # Extract payloads and execute
    extract_payloads
    execute_exploit
    install_kernelsu "$kmi"
    
    # Cleanup
    rm -f "$EXPLOIT_FILE" "$EXPLOIT_LOG"
    
    info ""
    info "════════════════════════════════════════════"
    info "✓ SUCCESS — KernelSU installed!"
    info "════════════════════════════════════════════"
    info ""
    info "Next: Open ReSukiSU Manager → Grant root to apps"
    info "Test: su -c 'id'  (should return uid=0)"
}

# ============================================================================
# EMBEDDED PAYLOADS (Base64-Encoded)
# ============================================================================
HELPER_B64=''
EXPLOIT_B64=''
KSUD_B64=''

# Run main
main "$@"
